SELECT CASE WHEN quantity >= 199 THEN 'high' WHEN quantity >= 117 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(quantity) AS total_quantity, COUNT(*) AS cnt, ROUND(SUM(quantity) * 100.0 / SUM(SUM(quantity)) OVER (), 2) AS pct_of_total FROM inventory WHERE last_restock <= '2025-01-01' GROUP BY CASE WHEN quantity >= 199 THEN 'high' WHEN quantity >= 117 THEN 'mid' ELSE 'low' END ORDER BY cnt DESC;
